    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpGno = GNO()
        tmpGno.Init(buf, pos)
        return cls.InitFromObj(tmpGno)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpGno):
        x = GNOT()
        x._UnPack(tmpGno)
        return x

    # GNOT
    def _UnPack(self, GNO):
        if GNO is None:
            return
        self.ID = GNO.ID()
        self.RECEIVER_ID = GNO.RECEIVER_ID()
        self.RECEIVER_TYPE = GNO.RECEIVER_TYPE()
        self.ANTENNA_ID = GNO.ANTENNA_ID()
        self.ANTENNA_TYPE = GNO.ANTENNA_TYPE()
        self.FIRMWARE_VERSION = GNO.FIRMWARE_VERSION()
        self.EPOCH = GNO.EPOCH()
        self.CLOCK_OFFSET = GNO.CLOCK_OFFSET()
        self.CLOCK_DRIFT = GNO.CLOCK_DRIFT()
        self.LATITUDE = GNO.LATITUDE()
        self.LONGITUDE = GNO.LONGITUDE()
        self.ALTITUDE = GNO.ALTITUDE()
        self.APPROX_X = GNO.APPROX_X()
        self.APPROX_Y = GNO.APPROX_Y()
        self.APPROX_Z = GNO.APPROX_Z()
        self.INTERVAL = GNO.INTERVAL()
        self.NUM_SATS = GNO.NUM_SATS()
        self.PDOP = GNO.PDOP()
        self.HDOP = GNO.HDOP()
        self.VDOP = GNO.VDOP()
        if not GNO.SAT_OBSIsNone():
            self.SAT_OBS = []
            for i in range(GNO.SAT_OBSLength()):
                if GNO.SAT_OBS(i) is None:
                    self.SAT_OBS.append(None)
                else:
                    gnssSatObs_ = gnssSatObs.gnssSatObsT.InitFromObj(GNO.SAT_OBS(i))
                    self.SAT_OBS.append(gnssSatObs_)
        if not GNO.OBS_CODE_SETIsNone():
            self.OBS_CODE_SET = []
            for i in range(GNO.OBS_CODE_SETLength()):
                self.OBS_CODE_SET.append(GNO.OBS_CODE_SET(i))
        self.NOTES = GNO.NOTES()
        self.TIME_SYSTEM = GNO.TIME_SYSTEM()
        self.EPOCH_FLAG = GNO.EPOCH_FLAG()
        self.MARKER_NAME = GNO.MARKER_NAME()
        self.MARKER_NUMBER = GNO.MARKER_NUMBER()
        self.MARKER_TYPE = GNO.MARKER_TYPE()
        self.OBSERVER = GNO.OBSERVER()
        self.AGENCY = GNO.AGENCY()
        if not GNO.ANTENNA_DELTA_HENIsNone():
            if np is None:
                self.ANTENNA_DELTA_HEN = []
                for i in range(GNO.ANTENNA_DELTA_HENLength()):
                    self.ANTENNA_DELTA_HEN.append(GNO.ANTENNA_DELTA_HEN(i))
            else:
                self.ANTENNA_DELTA_HEN = GNO.ANTENNA_DELTA_HENAsNumpy()
        if not GNO.PHASE_SHIFTSIsNone():
            self.PHASE_SHIFTS = []
            for i in range(GNO.PHASE_SHIFTSLength()):
                self.PHASE_SHIFTS.append(GNO.PHASE_SHIFTS(i))
        self.SIGNAL_STRENGTH_UNIT = GNO.SIGNAL_STRENGTH_UNIT()
        self.LEAP_SECONDS = GNO.LEAP_SECONDS()
        self.HAS_LEAP_SECONDS = GNO.HAS_LEAP_SECONDS()

    # GNOT
    def Pack(self, builder):
        if self.ID is not None:
            ID = builder.CreateString(self.ID)
        if self.RECEIVER_ID is not None:
            RECEIVER_ID = builder.CreateString(self.RECEIVER_ID)
        if self.RECEIVER_TYPE is not None:
            RECEIVER_TYPE = builder.CreateString(self.RECEIVER_TYPE)
        if self.ANTENNA_ID is not None:
            ANTENNA_ID = builder.CreateString(self.ANTENNA_ID)
        if self.ANTENNA_TYPE is not None:
            ANTENNA_TYPE = builder.CreateString(self.ANTENNA_TYPE)
        if self.FIRMWARE_VERSION is not None:
            FIRMWARE_VERSION = builder.CreateString(self.FIRMWARE_VERSION)
        if self.EPOCH is not None:
            EPOCH = builder.CreateString(self.EPOCH)
        if self.SAT_OBS is not None:
            SAT_OBSlist = []
            for i in range(len(self.SAT_OBS)):
                SAT_OBSlist.append(self.SAT_OBS[i].Pack(builder))
            GNOStartSAT_OBSVector(builder, len(self.SAT_OBS))
            for i in reversed(range(len(self.SAT_OBS))):
                builder.PrependUOffsetTRelative(SAT_OBSlist[i])
            SAT_OBS = builder.EndVector()
        if self.OBS_CODE_SET is not None:
            OBS_CODE_SETlist = []
            for i in range(len(self.OBS_CODE_SET)):
                OBS_CODE_SETlist.append(builder.CreateString(self.OBS_CODE_SET[i]))
            GNOStartOBS_CODE_SETVector(builder, len(self.OBS_CODE_SET))
            for i in reversed(range(len(self.OBS_CODE_SET))):
                builder.PrependUOffsetTRelative(OBS_CODE_SETlist[i])
            OBS_CODE_SET = builder.EndVector()
        if self.NOTES is not None:
            NOTES = builder.CreateString(self.NOTES)
        if self.TIME_SYSTEM is not None:
            TIME_SYSTEM = builder.CreateString(self.TIME_SYSTEM)
        if self.MARKER_NAME is not None:
            MARKER_NAME = builder.CreateString(self.MARKER_NAME)
        if self.MARKER_NUMBER is not None:
            MARKER_NUMBER = builder.CreateString(self.MARKER_NUMBER)
        if self.MARKER_TYPE is not None:
            MARKER_TYPE = builder.CreateString(self.MARKER_TYPE)
        if self.OBSERVER is not None:
            OBSERVER = builder.CreateString(self.OBSERVER)
        if self.AGENCY is not None:
            AGENCY = builder.CreateString(self.AGENCY)
        if self.ANTENNA_DELTA_HEN is not None:
            if np is not None and type(self.ANTENNA_DELTA_HEN) is np.ndarray:
                ANTENNA_DELTA_HEN = builder.CreateNumpyVector(self.ANTENNA_DELTA_HEN)
            else:
                GNOStartANTENNA_DELTA_HENVector(builder, len(self.ANTENNA_DELTA_HEN))
                for i in reversed(range(len(self.ANTENNA_DELTA_HEN))):
                    builder.PrependFloat64(self.ANTENNA_DELTA_HEN[i])
                ANTENNA_DELTA_HEN = builder.EndVector()
        if self.PHASE_SHIFTS is not None:
            PHASE_SHIFTSlist = []
            for i in range(len(self.PHASE_SHIFTS)):
                PHASE_SHIFTSlist.append(builder.CreateString(self.PHASE_SHIFTS[i]))
            GNOStartPHASE_SHIFTSVector(builder, len(self.PHASE_SHIFTS))
            for i in reversed(range(len(self.PHASE_SHIFTS))):
                builder.PrependUOffsetTRelative(PHASE_SHIFTSlist[i])
            PHASE_SHIFTS = builder.EndVector()
        if self.SIGNAL_STRENGTH_UNIT is not None:
            SIGNAL_STRENGTH_UNIT = builder.CreateString(self.SIGNAL_STRENGTH_UNIT)
        GNOStart(builder)
        if self.ID is not None:
            GNOAddID(builder, ID)
        if self.RECEIVER_ID is not None:
            GNOAddRECEIVER_ID(builder, RECEIVER_ID)
        if self.RECEIVER_TYPE is not None:
            GNOAddRECEIVER_TYPE(builder, RECEIVER_TYPE)
        if self.ANTENNA_ID is not None:
            GNOAddANTENNA_ID(builder, ANTENNA_ID)
        if self.ANTENNA_TYPE is not None:
            GNOAddANTENNA_TYPE(builder, ANTENNA_TYPE)
        if self.FIRMWARE_VERSION is not None:
            GNOAddFIRMWARE_VERSION(builder, FIRMWARE_VERSION)
        if self.EPOCH is not None:
            GNOAddEPOCH(builder, EPOCH)
        GNOAddCLOCK_OFFSET(builder, self.CLOCK_OFFSET)
        GNOAddCLOCK_DRIFT(builder, self.CLOCK_DRIFT)
        GNOAddLATITUDE(builder, self.LATITUDE)
        GNOAddLONGITUDE(builder, self.LONGITUDE)
        GNOAddALTITUDE(builder, self.ALTITUDE)
        GNOAddAPPROX_X(builder, self.APPROX_X)
        GNOAddAPPROX_Y(builder, self.APPROX_Y)
        GNOAddAPPROX_Z(builder, self.APPROX_Z)
        GNOAddINTERVAL(builder, self.INTERVAL)
        GNOAddNUM_SATS(builder, self.NUM_SATS)
        GNOAddPDOP(builder, self.PDOP)
        GNOAddHDOP(builder, self.HDOP)
        GNOAddVDOP(builder, self.VDOP)
        if self.SAT_OBS is not None:
            GNOAddSAT_OBS(builder, SAT_OBS)
        if self.OBS_CODE_SET is not None:
            GNOAddOBS_CODE_SET(builder, OBS_CODE_SET)
        if self.NOTES is not None:
            GNOAddNOTES(builder, NOTES)
        if self.TIME_SYSTEM is not None:
            GNOAddTIME_SYSTEM(builder, TIME_SYSTEM)
        GNOAddEPOCH_FLAG(builder, self.EPOCH_FLAG)
        if self.MARKER_NAME is not None:
            GNOAddMARKER_NAME(builder, MARKER_NAME)
        if self.MARKER_NUMBER is not None:
            GNOAddMARKER_NUMBER(builder, MARKER_NUMBER)
        if self.MARKER_TYPE is not None:
            GNOAddMARKER_TYPE(builder, MARKER_TYPE)
        if self.OBSERVER is not None:
            GNOAddOBSERVER(builder, OBSERVER)
        if self.AGENCY is not None:
            GNOAddAGENCY(builder, AGENCY)
        if self.ANTENNA_DELTA_HEN is not None:
            GNOAddANTENNA_DELTA_HEN(builder, ANTENNA_DELTA_HEN)
        if self.PHASE_SHIFTS is not None:
            GNOAddPHASE_SHIFTS(builder, PHASE_SHIFTS)
        if self.SIGNAL_STRENGTH_UNIT is not None:
            GNOAddSIGNAL_STRENGTH_UNIT(builder, SIGNAL_STRENGTH_UNIT)
        GNOAddLEAP_SECONDS(builder, self.LEAP_SECONDS)
        GNOAddHAS_LEAP_SECONDS(builder, self.HAS_LEAP_SECONDS)
        GNO = GNOEnd(builder)
        return GNO
